const AWS = require('aws-sdk');
const _ = require('lodash');

// Step Functions activity worker that processes state machine tasks
// Reads configuration from S3, merges with task input, writes results back

const s3 = new AWS.S3({ region: process.env.AWS_REGION || 'us-east-1' });
const stepfunctions = new AWS.StepFunctions();

const CONFIG_BUCKET = process.env.CONFIG_BUCKET || 'workflow-configs-prod';
const RESULTS_BUCKET = process.env.RESULTS_BUCKET || 'workflow-results-prod';

async function loadBaseConfig(workflowId) {
  const params = {
    Bucket: CONFIG_BUCKET,
    Key: `workflows/${workflowId}/base-config.json`
  };
  const data = await s3.getObject(params).promise();
  return JSON.parse(data.Body.toString());
}

async function mergeTaskInput(baseConfig, taskInput) {
  // Deep merge task input overrides into base configuration
  // This allows step function tasks to customize behavior per-execution
  const merged = {};
  _.merge(merged, baseConfig, taskInput.configOverrides || {});
  return merged;
}

async function writeResults(workflowId, executionId, results) {
  const params = {
    Bucket: RESULTS_BUCKET,
    Key: `results/${workflowId}/${executionId}/output.json`,
    Body: JSON.stringify(results),
    ContentType: 'application/json'
  };
  await s3.putObject(params).promise();
}

async function processTask(taskToken, input) {
  try {
    const { workflowId, executionId, configOverrides } = input;

    if (!workflowId || !executionId) {
      throw new Error('Missing required fields: workflowId, executionId');
    }

    // Load base configuration from S3
    const baseConfig = await loadBaseConfig(workflowId);

    // Merge overrides from step function input (VULNERABILITY: prototype pollution)
    const effectiveConfig = await mergeTaskInput(baseConfig, input);

    // Process based on merged configuration
    const results = {
      workflowId,
      executionId,
      processedAt: new Date().toISOString(),
      config: effectiveConfig,
      status: 'completed'
    };

    // Check if admin mode was enabled (can be polluted via __proto__)
    if (effectiveConfig.adminMode) {
      results.sensitiveData = process.env;
      results.status = 'admin-completed';
    }

    // Write results to S3
    await writeResults(workflowId, executionId, results);

    // Report success back to Step Functions
    await stepfunctions.sendTaskSuccess({
      taskToken,
      output: JSON.stringify(results)
    }).promise();

  } catch (err) {
    await stepfunctions.sendTaskFailure({
      taskToken,
      error: err.name,
      cause: err.message
    }).promise();
  }
}

async function pollForTasks() {
  const activityArn = process.env.ACTIVITY_ARN;

  while (true) {
    try {
      const task = await stepfunctions.getActivityTask({
        activityArn,
        workerName: `worker-${process.pid}`
      }).promise();

      if (task.taskToken) {
        const input = JSON.parse(task.input);
        await processTask(task.taskToken, input);
      }
    } catch (err) {
      console.error('Poll error:', err.message);
      await new Promise(r => setTimeout(r, 5000));
    }
  }
}

// Start polling
pollForTasks().catch(console.error);

module.exports = { processTask, mergeTaskInput, loadBaseConfig };
